const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};
const labels={no_listing:'Sin precio disponible',not_configured:'Sin conectar',busy:'Consulta en cola',rate_limited:'Límite temporal del mercado',access_denied:'Acceso no disponible',unavailable:'No disponible ahora'};
const wearLabels={'Factory New':'Recién fabricado','Minimal Wear':'Casi nuevo','Field-Tested':'Algo desgastado','Well-Worn':'Bastante desgastado','Battle-Scarred':'Deplorable'};
const lifetime=30*60*1000;
let catalogPromise;
export function createMarketPrices(dialog){
 const $=s=>dialog.querySelector(s);let context=null;
 function stop(){if(!context)return;context.controller?.abort();clearTimeout(context.timer);clearTimeout(context.retry);context=null}
 function empty(text='Consultando…'){$('#marketQuoteRows').replaceChildren(...['Steam','CSFloat'].map(name=>{const row=node('tr');row.append(node('th',name),node('td',text),node('td','—'),node('td',''));return row}))}
 function render(data){const body=$('#marketQuoteRows');body.replaceChildren();for(const provider of ['steam','csfloat']){const quote=data.providers.find(p=>p.provider===provider)||{status:'unavailable'},row=node('tr'),name=node('th',provider==='steam'?'Steam':'CSFloat'),value=node('td'),date=node('td'),action=node('td');name.scope='row';
  if(Number.isSafeInteger(quote.price)&&quote.price>=0){value.append(node('strong',new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(quote.price/100)));if(quote.stale||quote.warning)value.append(node('small','Dato anterior · no se pudo actualizar'));}
  else{value.append(node('span',labels[quote.status]||'Sin datos'));value.className='quote-unavailable'}
  const when=quote.observed_at&&new Date(quote.observed_at);date.textContent=when&&Number.isFinite(when.getTime())?new Intl.DateTimeFormat('es-EC',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(when):'—';
  if(quote.link){try{const url=new URL(quote.link);if(url.protocol==='https:'&&['steamcommunity.com','csfloat.com'].includes(url.hostname)){const link=node('a',provider==='steam'?'Ver ofertas ↗':'Ir al mercado ↗');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';action.append(link)}}catch{}}
  row.append(name,value,date,action);body.append(row)}
  $('#marketConnectionNote').textContent=data.providers.some(p=>p.provider==='csfloat'&&p.status==='not_configured')?'CSFloat aún no está conectado. Puedes abrir su mercado desde el enlace.':'';
 }
 async function refresh(retry=false){const c=context;if(!c)return;clearTimeout(c.timer);clearTimeout(c.retry);c.controller?.abort();const controller=new AbortController();c.controller=controller;const revision=++c.revision;$('#marketQuoteRefresh').disabled=true;$('#marketQuoteStatus').textContent='Consultando precios…';
  try{const response=await fetch(LOADOUT_CLOUD.url+'/functions/v1/market-prices',{method:'POST',headers:{'Content-Type':'application/json',apikey:LOADOUT_CLOUD.publishableKey},body:JSON.stringify({skin:c.id,wear:$('#marketWear').value,variant:$('#marketVariant').value}),signal:controller.signal});if(!response.ok)throw Error();const value=await response.json();if(context!==c||c.revision!==revision)return;if(!Array.isArray(value.providers))throw Error();render(value);$('#marketQuoteStatus').textContent='Precios en USD · actualización automática al mantener abierto este detalle · caché de 30 min.';
   const delay=Math.max(0,...value.providers.map(p=>Number(p.retry_after)||0));if(delay&&!retry&&delay<=30)c.retry=setTimeout(()=>refresh(true),(delay+1)*1000);
   const times=value.providers.filter(p=>p.observed_at&&!p.warning&&['ok','no_listing'].includes(p.status)).map(p=>new Date(p.observed_at).getTime()+lifetime);const next=times.length?Math.max(6000,Math.min(...times)-Date.now()+1000):5*60*1000;c.next=Date.now()+next;c.timer=setTimeout(()=>{if(!document.hidden)refresh();},next);
  }catch(error){if(controller.signal.aborted||context!==c||c.revision!==revision)return;empty('No disponible ahora');$('#marketQuoteStatus').textContent='No se pudieron consultar los mercados. Puedes volver a intentarlo.';c.next=Date.now()+5*60*1000;c.timer=setTimeout(()=>{if(!document.hidden)refresh();},5*60*1000)}finally{if(context===c&&c.revision===revision)$('#marketQuoteRefresh').disabled=false}
 }
 $('#marketWear').onchange=()=>{empty();refresh()};$('#marketVariant').onchange=()=>{empty();refresh()};$('#marketQuoteRefresh').onclick=()=>refresh();dialog.addEventListener('close',stop);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&context&&Date.now()>=context.next)refresh()});
 return{async open(skin){stop();const c={id:skin.id,revision:0,next:Infinity,timer:null,retry:null,controller:null};context=c;empty();$('#marketQuoteRefresh').disabled=true;$('#marketConnectionNote').textContent='';$('#marketPhaseNote').textContent='';$('#marketQuoteStatus').textContent='Cargando variantes de mercado…';$('#marketWear').replaceChildren(new Option('Cargando…',''));$('#marketVariant').replaceChildren(new Option('Normal','normal'));
   try{catalogPromise??=fetch('market-items.json').then(r=>{if(!r.ok)throw Error();return r.json()}).catch(e=>{catalogPromise=null;throw e});const items=await catalogPromise;if(context!==c)return;const item=items[skin.id];if(!item)throw Error();$('#marketWear').replaceChildren(...(item.wears.length?item.wears.map(w=>new Option(wearLabels[w]||w,w)):[new Option('Sin desgaste','')]));if(item.wears.includes('Field-Tested'))$('#marketWear').value='Field-Tested';if(item.stattrak)$('#marketVariant').append(new Option('StatTrak™','stattrak'));if(item.souvenir)$('#marketVariant').append(new Option('Souvenir','souvenir'));if(item.phase)$('#marketPhaseNote').textContent='Steam agrupa las fases Doppler en un mismo precio. CSFloat consulta la fase seleccionada.';refresh();}
   catch{if(context!==c)return;empty('Sin datos de mercado');$('#marketQuoteStatus').textContent='No se pudieron cargar las variantes de esta skin.'}
 },stop};
}
